const C=document.getElementById('C'),X=C.getContext('2d');
const W=800,H=600;C.width=W;C.height=H;
// === SOUND SYSTEM (Web Audio API) ===
let audioCtx=null,soundOn=true;
function initAudio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)()}
function playTone(freq,dur,type='square',vol=0.15){
  if(!soundOn||!audioCtx)return;
  try{let o=audioCtx.createOscillator(),g=audioCtx.createGain();
  o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);
  g.gain.setValueAtTime(vol,audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+dur);
  o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}
}
function sfxBounce(){playTone(440,0.08,'sine',0.1)}
function sfxBrickHit(){playTone(600+Math.random()*200,0.1,'square',0.12)}
function sfxBrickBreak(){playTone(800+Math.random()*400,0.15,'sawtooth',0.1)}
function sfxExplosion(){playTone(100,0.3,'sawtooth',0.2);playTone(80,0.4,'sine',0.15)}
function sfxUpgrade(){playTone(523,0.1,'sine',0.15);setTimeout(()=>playTone(659,0.1,'sine',0.15),100);setTimeout(()=>playTone(784,0.2,'sine',0.15),200)}
function sfxLoseLife(){playTone(200,0.3,'sawtooth',0.15);setTimeout(()=>playTone(150,0.4,'sawtooth',0.12),150)}
function sfxGameOver(){playTone(300,0.2,'sawtooth',0.15);setTimeout(()=>playTone(200,0.3,'sawtooth',0.12),200);setTimeout(()=>playTone(100,0.5,'sawtooth',0.1),400)}
function sfxPowerup(){playTone(880,0.08,'sine',0.12);setTimeout(()=>playTone(1100,0.12,'sine',0.12),80)}
function sfxBoss(){playTone(60,0.5,'sawtooth',0.2);playTone(80,0.6,'square',0.15)}
function sfxWave(){playTone(440,0.15,'sine',0.1);setTimeout(()=>playTone(660,0.15,'sine',0.1),120)}
function toggleSound(){soundOn=!soundOn;document.getElementById('sound-toggle').textContent=soundOn?'🔊':'🔇'}

// === SCREEN SHAKE ===
let shakeX=0,shakeY=0,shakeMag=0,shakeDur=0;
function triggerShake(mag,dur){shakeMag=mag;shakeDur=dur}
function updateShake(){
  if(shakeDur>0){shakeDur--;shakeX=(Math.random()-.5)*shakeMag*2;shakeY=(Math.random()-.5)*shakeMag*2;shakeMag*=0.9}
  else{shakeX=0;shakeY=0}
}

// === FLOATING TEXT ===
let floatingTexts=[];
function addFloatText(x,y,text,color='#fff',size=16){
  floatingTexts.push({x,y,text,color,size,life:1,vy:-2})
}

// === GAME STATE ===
let score=0,lives=3,wave=1,combo=0,maxCombo=0,gameOver=false,running=false,upgrading=false;
let paddleW=120,paddleH=14,ballR=8;
let px=W/2-60,py=H-30,bx=W/2,by=H-50,bdx=4,bdy=-4;
let stars=[],particles=[],buffs=[],powerups=[];
for(let i=0;i<100;i++)stars.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*2,a:Math.random(),s:Math.random()*0.02+0.005});
const colors=['#f0f','#a0f','#08f','#0ff','#0f0','#ff0','#f80','#f44','#fff'];
let bricks=[];
let brickSpeed=0.15,spawnTimer=0,spawnInterval=180,gameTime=0,difficultyLevel=1;
let upgradeCount=0,hiScore=parseInt(localStorage.getItem('neonBreakoutHi'))||0;
document.getElementById('hiVal').textContent=hiScore;

function getNextThreshold(){return 500+upgradeCount*700+upgradeCount*upgradeCount*100}
let nextUpgradeScore=getNextThreshold();

// === UPGRADES ===
const UPGRADES=[
  {id:'life',icon:'\u2764',name:'Extra Life',desc:'+1 Life',rarity:'common',apply:()=>{lives++;document.getElementById('livesVal').textContent=lives}},
  {id:'paddle_w',icon:'\u2194',name:'Wide Paddle',desc:'+30 paddle width',rarity:'common',apply:()=>{paddleW+=30}},
  {id:'big_ball',icon:'\u25CF',name:'Big Ball',desc:'+3 ball radius',rarity:'common',apply:()=>{ballR+=3}},
  {id:'slow',icon:'\u23F1',name:'Slow Motion',desc:'-15% ball speed',rarity:'common',apply:()=>{let s=Math.sqrt(bdx*bdx+bdy*bdy);let ns=s*0.85;let r=ns/s;bdx*=r;bdy*=r}},
  {id:'slow_scroll',icon:'\u23F1',name:'Slow Bricks',desc:'Bricks fall -20%',rarity:'common',apply:()=>{brickSpeed*=0.8}},
  {id:'score_x',icon:'\u00D72',name:'Score Boost',desc:'2x score multiplier',rarity:'rare',apply:()=>{scoreMult*=2}},
  {id:'magnet',icon:'\u{1F9F2}',name:'Magnet Paddle',desc:'Ball sticks on catch',rarity:'rare',apply:()=>{magnet=true}},
  {id:'pierce',icon:'\u2694',name:'Pierce Shot',desc:'Ball pierces bricks',rarity:'epic',apply:()=>{pierce++}},
  {id:'multi',icon:'\u2726',name:'Multi Ball',desc:'+1 extra ball',rarity:'epic',apply:()=>{spawnExtraBall()}},
  {id:'fireball',icon:'\u{1F525}',name:'Fireball',desc:'Explosive on impact',rarity:'legendary',apply:()=>{fireball=true}},
  {id:'shield',icon:'\u{1F6E1}',name:'Shield',desc:'One-time bottom save',rarity:'rare',apply:()=>{shieldCount++}},
  {id:'combo_keep',icon:'\u{1F517}',name:'Combo Lock',desc:'Combo never resets',rarity:'legendary',apply:()=>{comboLock=true}},
  {id:'laser',icon:'\u{1F4A1}',name:'Laser Paddle',desc:'Shoot lasers on click',rarity:'epic',apply:()=>{laserMode=true}},
  {id:'nuke',icon:'\u{1F4A5}',name:'Screen Nuke',desc:'Destroy all on-screen bricks',rarity:'legendary',apply:()=>{for(let b of bricks){if(b.alive){b.alive=false;score+=50*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,8)}}document.getElementById('scoreVal').textContent=score}},
];
let scoreMult=1,magnet=false,pierce=0,fireball=false,shieldCount=0,comboLock=false,laserMode=false;
let extraBalls=[],lasers=[];

// === POWERUP DROPS ===
const POWERUP_TYPES=[
  {id:'life',icon:'\u2764',color:'#f44',name:'+1 Life',apply:()=>{lives++;document.getElementById('livesVal').textContent=lives}},
  {id:'wide',icon:'\u2194',color:'#0ff',name:'Wide +20',apply:()=>{paddleW+=20}},
  {id:'slow',icon:'\u23F1',color:'#ff0',name:'Slow Ball',apply:()=>{let s=Math.sqrt(bdx*bdx+bdy*bdy);let r=(s*0.8)/s;bdx*=r;bdy*=r}},
  {id:'shield',icon:'\u{1F6E1}',color:'#f0f',name:'Shield',apply:()=>{shieldCount++}},
  {id:'multi',icon:'\u2726',color:'#0f0',name:'Multi Ball',apply:()=>{spawnExtraBall()}},
  {id:'nuke_mini',icon:'\u2737',color:'#f80',name:'Clear Row',apply:()=>{for(let b of bricks){if(b.alive&&Math.abs(b.y+ b.h/2-by)<30){b.alive=false;score+=30*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,6)}}}},
];
function maybeDropPowerup(x,y){
  if(Math.random()<0.06){ // 6% chance
    let p=POWERUP_TYPES[Math.floor(Math.random()*POWERUP_TYPES.length)];
    powerups.push({x,y,dy:1.5,type:p,life:1})
  }
}
PART2_EOF
