cat >> /tmp/breakout_v3.html << 'PART3_EOF'
// === BOSS BRICKS ===
let bossActive=false,bossHP=0,bossMaxHP=0,bossX=0,bossY=0,bossW=0,bossH=0,bossColor='#f00',bossTimer=0;
function spawnBoss(){
  bossActive=true;
  bossHP=20+difficultyLevel*5;bossMaxHP=bossHP;
  bossW=200;bossH=40;bossX=W/2-bossW/2;bossY=-bossH-10;
  bossColor=colors[Math.floor(Math.random()*colors.length)];
  bossTimer=0;
  sfxBoss();
  addFloatText(W/2,H/2-50,'⚠ BOSS ⚠','#f00',36);
  triggerShake(8,30);
}
function damageBoss(dmg){
  bossHP-=dmg;bossTimer=8;
  spawnParticles(bossX+Math.random()*bossW,bossY+Math.random()*bossH,bossColor,5);
  if(bossHP<=0){
    bossActive=false;
    let pts=500*scoreMult;
    score+=pts;
    addFloatText(bossX+bossW/2,bossY,'+'+pts,'#ff0',28);
    for(let i=0;i<60;i++)spawnParticles(bossX+Math.random()*bossW,bossY+Math.random()*bossH,bossColor,3);
    triggerShake(12,40);sfxExplosion();
    // Drop guaranteed powerup
    let p=POWERUP_TYPES[Math.floor(Math.random()*POWERUP_TYPES.length)];
    powerups.push({x:bossX+bossW/2,y:bossY+bossH,dy:1.5,type:p,life:1});
    document.getElementById('scoreVal').textContent=score;
    checkUpgradeThreshold();
  }
}

// === BRICK PATTERNS ===
const PATTERNS=['full','checker','diamond','v_shape','random_gap','fortress'];
function spawnRow(){
  let cols=10,bw=65,bh=20,gap=8;
  let maxHp=Math.min(1+Math.floor(difficultyLevel/2),6);
  let pattern=PATTERNS[Math.floor(Math.random()*PATTERNS.length)];
  let rowColor=colors[Math.floor(Math.random()*colors.length)];
  for(let c=0;c<cols;c++){
    let x=c*(bw+gap)+35,y=-bh-5;
    // Pattern filtering
    if(pattern==='checker'&&c%2===0)continue;
    if(pattern==='diamond'&&(c<2||c>7))continue;
    if(pattern==='v_shape'&&c!==Math.abs(c-4.5)<=(4.5-Math.abs(c-4.5))?c:0)continue;
    if(pattern==='random_gap'&&Math.random()<0.3)continue;
    if(pattern==='fortress'&&(c===0||c===cols-1))continue;
    let hp=1;
    let r=Math.random();
    if(difficultyLevel>=3&&r<0.2)hp=Math.min(maxHp,2);
    if(difficultyLevel>=5&&r<0.15)hp=Math.min(maxHp,3);
    if(difficultyLevel>=8&&r<0.1)hp=Math.min(maxHp,4);
    if(difficultyLevel>=12&&r<0.05)hp=Math.min(maxHp,5);
    let type='normal';
    if(difficultyLevel>=6&&Math.random()<0.08)type='armored';
    if(difficultyLevel>=10&&Math.random()<0.05)type='regen';
    if(type==='armored')hp=Math.ceil(hp*1.5);
    if(type==='regen')hp=Math.ceil(hp*1.3);
    bricks.push({x,y,w:bw,h:bh,color:rowColor,alive:true,hp,maxHp:hp,type});
  }
  wave++;
  document.getElementById('levelVal').textContent=wave;
  // Boss every 10 waves
  if(wave%10===0&&!bossActive)spawnBoss();
  // Wave announcement
  if(wave%5===0)announceWave(wave);
}

function announceWave(n){
  let el=document.getElementById('wave-announce');
  el.textContent='WAVE '+n;
  el.style.opacity='1';
  sfxWave();
  setTimeout(()=>{el.style.opacity='0'},1500);
}

function updateXPBar(){
  let prev=upgradeCount>0?(500+(upgradeCount-1)*700+(upgradeCount-1)*(upgradeCount-1)*100):0;
  let range=nextUpgradeScore-prev;
  let prog=Math.min(1,(score-prev)/range);
  document.getElementById('xp-bar').style.width=(prog*100)+'%';
  document.getElementById('xp-label').textContent='Next upgrade: '+nextUpgradeScore+' ('+Math.floor(prog*100)+'%)';
}

function flashLevelUp(){
  let el=document.getElementById('levelup-flash');
  el.style.opacity='1';
  setTimeout(()=>{el.style.opacity='0'},800);
}

function resetBall(){bx=W/2;by=H-50;let spd=4+difficultyLevel*0.15;bdx=spd*(Math.random()>.5?1:-1);bdy=-spd}
function spawnExtraBall(){
  let spd=Math.sqrt(bdx*bdx+bdy*bdy);
  extraBalls.push({x:bx,y:by,dx:spd*(Math.random()-.5)*2,dy:-spd,trail:[]});
}

function spawnParticles(x,y,color,n=15){
  for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*6,life:1,color,size:Math.random()*3+2})
}

function explodeBricks(bx2,by2,radius){
  for(let b of bricks){
    if(!b.alive)continue;
    let cx=b.x+b.w/2,cy=b.y+b.h/2;
    let dist=Math.sqrt((cx-bx2)**2+(cy-by2)**2);
    if(dist<radius){
      b.hp-=2;
      if(b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(cx,cy,b.color,15);addFloatText(cx,cy,'+'+100*combo*scoreMult,'#ff0',combo>10?20:14)}
    }
  }
}

function checkUpgradeThreshold(){
  if(score>=nextUpgradeScore){flashLevelUp();showUpgradeScreen()}
  updateXPBar();
}

function showUpgradeScreen(){
  upgrading=true;running=false;sfxUpgrade();
  let pool=[...UPGRADES];
  let picks=[];let tries=0;
  while(picks.length<3&&tries<50){
    tries++;
    let idx=Math.floor(Math.random()*pool.length);
    let u=pool[idx];
    let w=u.rarity==='common'?40:u.rarity==='rare'?25:u.rarity==='epic'?10:3;
    if(Math.random()*100<w&&!picks.find(p=>p.id===u.id)){picks.push(u)}
  }
  while(picks.length<3)picks.push(UPGRADES[Math.floor(Math.random()*UPGRADES.length)]);
  let html='';
  picks.forEach((u,i)=>{
    html+=`<div class="upgrade-card" onclick="pickUpgrade(${i})"><div class="icon">${u.icon}</div><div class="name">${u.name}</div><div class="desc">${u.desc}</div><span class="rarity rarity-${u.rarity}">${u.rarity.toUpperCase()}</span></div>`;
  });
  document.getElementById('upgrade-cards').innerHTML=html;
  document.getElementById('upgrade-sub').textContent='Upgrade #'+(upgradeCount+1)+' — Pick a power:';
  document.getElementById('upgrade-overlay').style.display='flex';
  window._upgradePicks=picks;
}

window.pickUpgrade=function(i){
  let u=window._upgradePicks[i];
  u.apply();sfxUpgrade();
  buffs.push({name:u.name,rarity:u.rarity});
  updateBuffDisplay();
  document.getElementById('upgrade-overlay').style.display='none';
  upgrading=false;running=true;
  upgradeCount++;nextUpgradeScore=getNextThreshold();updateXPBar();
};
function updateBuffDisplay(){
  let el=document.getElementById('buffs');
  el.innerHTML=buffs.map(b=>`<span class="buff-tag" style="border-color:${b.rarity==='legendary'?'#ff0':b.rarity==='epic'?'#f0f':b.rarity==='rare'?'#08f':'#0f0'}">${b.name}</span>`).join('');
}
PART3_EOF
