// === BRICK PATTERNS ===
const PATTERNS=['full','checker','diamond','v_shape','random_gap','fortress','cross'];
function spawnRow(){
  let cols=10,bw=65,bh=20,gap=8;
  let maxHp=Math.min(1+Math.floor(difficultyLevel/2),6);
  let pattern=PATTERNS[Math.floor(Math.random()*PATTERNS.length)];
  let rowColor=colors[Math.floor(Math.random()*colors.length)];
  for(let c=0;c<cols;c++){
    let x=c*(bw+gap)+35,y=-bh-5;
    if(pattern==='checker'&&c%2===0)continue;
    if(pattern==='diamond'&&(c<2||c>7))continue;
    if(pattern==='random_gap'&&Math.random()<0.3)continue;
    if(pattern==='fortress'&&(c===0||c===cols-1))continue;
    if(pattern==='cross'&&(c!==4&&c!==5))continue;
    let hp=1;
    let r=Math.random();
    if(difficultyLevel>=3&&r<0.2)hp=Math.min(maxHp,2);
    if(difficultyLevel>=5&&r<0.15)hp=Math.min(maxHp,3);
    if(difficultyLevel>=8&&r<0.1)hp=Math.min(maxHp,4);
    if(difficultyLevel>=12&&r<0.05)hp=Math.min(maxHp,5);
    let type='normal';
    if(difficultyLevel>=6&&Math.random()<0.08)type='armored';
    if(difficultyLevel>=10&&Math.random()<0.05)type='regen';
    if(type==='armored')hp=Math.ceil(hp*1.5);
    if(type==='regen')hp=Math.ceil(hp*1.3);
    bricks.push({x,y,w:bw,h:bh,color:rowColor,alive:true,hp,maxHp:hp,type});
  }
  wave++;document.getElementById('levelVal').textContent=wave;
  if(wave%10===0&&!bossActive)spawnBoss();
  if(wave%5===0)announceWave(wave);
}

function announceWave(n){
  let el=document.getElementById('wave-announce');
  el.textContent='WAVE '+n;el.style.opacity='1';sfxWave();
  setTimeout(()=>{el.style.opacity='0'},1500);
}

function updateXPBar(){
  let prev=upgradeCount>0?(500+(upgradeCount-1)*700+(upgradeCount-1)*(upgradeCount-1)*100):0;
  let range=nextUpgradeScore-prev;
  let prog=Math.min(1,(score-prev)/range);
  document.getElementById('xp-bar').style.width=(prog*100)+'%';
  document.getElementById('xp-label').textContent='Next upgrade: '+nextUpgradeScore+' ('+Math.floor(prog*100)+'%)';
}

function flashLevelUp(){
