  extraBalls.push({x:bx,y:by,dx:spd*(Math.random()-.5)*2,dy:-spd,trail:[]});
}

function spawnParticles(x,y,color,n=15){
  for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*6,life:1,color,size:Math.random()*3+1.5})
}

function explodeBricks(bx2,by2,radius){
  for(let b of bricks){
    if(!b.alive)continue;
    let cx=b.x+b.w/2,cy=b.y+b.h/2;
    if(Math.sqrt((cx-bx2)**2+(cy-by2)**2)<radius){
