}

function showUpgradeScreen(){
  upgrading=true;running=false;sfxUpgrade();
  let pool=[...UPGRADES];let picks=[];let tries=0;
  while(picks.length<3&&tries<50){
    tries++;let idx=Math.floor(Math.random()*pool.length);let u=pool[idx];
    let w=u.rarity==='common'?40:u.rarity==='rare'?25:u.rarity==='epic'?10:3;
    if(Math.random()*100<w&&!picks.find(p=>p.id===u.id))picks.push(u);
  }
  while(picks.length<3)picks.push(UPGRADES[Math.floor(Math.random()*UPGRADES.length)]);
  let html='';
  picks.forEach((u,i)=>{
    html+=`<div class="upgrade-card" onclick="pickUpgrade(${i})"><div class="icon">${u.icon}</div><div class="name">${u.name}</div><div class="desc">${u.desc}</div><span class="rarity rarity-${u.rarity}">${u.rarity.toUpperCase()}</span></div>`;
  });
  document.getElementById('upgrade-cards').innerHTML=html;
  document.getElementById('upgrade-sub').textContent='Upgrade #'+(upgradeCount+1)+' — Pick a power:';
  document.getElementById('upgrade-overlay').style.display='flex';
  window._upgradePicks=picks;
}

window.pickUpgrade=function(i){
  let u=window._upgradePicks[i];u.apply();sfxUpgrade();
  buffs.push({name:u.name,rarity:u.rarity});
  updateBuffDisplay();
  document.getElementById('upgrade-overlay').style.display='none';
  upgrading=false;running=true;
  upgradeCount++;nextUpgradeScore=getNextThreshold();updateXPBar();
};

function updateBuffDisplay(){
  let el=document.getElementById('buffs');
  el.innerHTML=buffs.map(b=>`<span class="buff-tag" style="border-color:${b.rarity==='legendary'?'#ff0':b.rarity==='epic'?'#f0f':b.rarity==='rare'?'#08f':'#0f0'}">${b.name}</span>`).join('');
}

