// === UPDATE ===
let magnetHeld=false;
function update(){
  if(!running||gameOver||upgrading||paused)return;
  gameTime++;
  // Difficulty scaling
  if(gameTime%600===0){difficultyLevel++;brickSpeed+=0.02;spawnInterval=Math.max(60,spawnInterval-6)}
  // Spawn bricks
  spawnTimer++;
  if(spawnTimer>=spawnInterval){spawnTimer=0;spawnRow()}
  // Move bricks down
  for(let i=bricks.length-1;i>=0;i--){
    let b=bricks[i];
    if(!b.alive){bricks.splice(i,1);continue}
    b.y+=brickSpeed;
    if(b.type==='regen'&&b.hp<b.maxHp&&gameTime%120===0)b.hp=Math.min(b.maxHp,b.hp+1);
    // Brick reached paddle zone = lose life
    if(b.y+b.h>=py){
      b.alive=false;spawnParticles(b.x+b.w/2,b.y+b.h/2,'#f00',20);
      if(shieldCount>0){shieldCount--;addFloatText(b.x+b.w/2,py,'SHIELD!','#f0f',20);sfxPowerup();triggerShake(4,10);continue}
      lives--;document.getElementById('livesVal').textContent=lives;sfxLoseLife();triggerShake(6,20);
      if(!comboLock){combo=0;document.getElementById('comboVal').textContent=combo}
      if(lives<=0){endGame();return}
    }
  }
  // Boss movement
  if(bossActive){
    bossY+=0.3;if(bossY>50)bossY=50;
    bossX+=Math.sin(gameTime*0.02)*2;
    bossX=Math.max(0,Math.min(W-bossW,bossX));
    if(bossTimer>0)bossTimer--;
  }
  // Paddle
  px=Math.max(0,Math.min(W-paddleW,px));
  // Main ball
  if(!magnetHeld){
    bx+=bdx;by+=bdy;
    if(bx-ballR<0){bx=ballR;bdx=Math.abs(bdx);sfxBounce()}
    if(bx+ballR>W){bx=W-ballR;bdx=-Math.abs(bdx);sfxBounce()}
    if(by-ballR<0){by=ballR;bdy=Math.abs(bdy);sfxBounce()}
    // Paddle bounce
    if(bdy>0&&by+ballR>=py&&by+ballR<=py+paddleH+4&&bx>=px-4&&bx<=px+paddleW+4){
      let hit=(bx-(px+paddleW/2))/(paddleW/2);
      let spd=Math.sqrt(bdx*bdx+bdy*bdy);
      let angle=hit*Math.PI/3;
      bdx=spd*Math.sin(angle);bdy=-spd*Math.cos(angle);
      by=py-ballR;
      if(magnet){magnetHeld=true}
      sfxBounce();spawnParticles(bx,py,'#0ff',5);
    }
    // Brick collision
    for(let b of bricks){
      if(!b.alive)continue;
      if(bx+ballR>b.x&&bx-ballR<b.x+b.w&&by+ballR>b.y&&by-ballR<b.y+b.h){
        b.hp--;
        if(b.hp<=0){
          b.alive=false;combo++;maxCombo=Math.max(maxCombo,combo);
          let pts=100*combo*scoreMult;score+=pts;
          addFloatText(b.x+b.w/2,b.y,'+'+pts,combo>10?'#ff0':'#fff',combo>10?20:14);
          spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,12);sfxBrickBreak();
          if(fireball)explodeBricks(b.x+b.w/2,b.y+b.h/2,80);
          maybeDropPowerup(b.x+b.w/2,b.y+b.h/2);
          triggerShake(combo>10?4:2,combo>10?10:5);
        }else{sfxBrickHit();spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,4)}
        if(pierce<=0){bdy=-bdy;by+=bdy>0?-2:2}
        document.getElementById('scoreVal').textContent=score;
        document.getElementById('comboVal').textContent=combo;
        checkUpgradeThreshold();
        if(pierce<=0)break;
      }
    }
    // Boss collision
    if(bossActive&&bx+ballR>bossX&&bx-ballR<bossX+bossW&&by+ballR>bossY&&by-ballR<bossY+bossH){
      damageBoss(1);bdy=-bdy;sfxBrickHit();triggerShake(3,8);
    }
    // Ball lost
    if(by>H+20){
      if(shieldCount>0){shieldCount--;by=py-ballR;bdy=-Math.abs(bdy);addFloatText(bx,H-20,'SHIELD!','#f0f',24);sfxPowerup();triggerShake(5,15)}
      else if(extraBalls.length>0){let eb=extraBalls.pop();bx=eb.x;by=eb.y;bdx=eb.dx;bdy=eb.dy}
      else{lives--;document.getElementById('livesVal').textContent=lives;sfxLoseLife();triggerShake(6,20);
        if(!comboLock){combo=0;document.getElementById('comboVal').textContent=combo}
        if(lives<=0){endGame();return}
        resetBall();
      }
    }
  }else{bx=px+paddleW/2;by=py-ballR}
  // Extra balls
  for(let i=extraBalls.length-1;i>=0;i--){
    let eb=extraBalls[i];eb.x+=eb.dx;eb.y+=eb.dy;
    if(eb.x<ballR||eb.x>W-ballR)eb.dx=-eb.dx;
    if(eb.y<ballR)eb.dy=Math.abs(eb.dy);
    if(eb.y>H+20){extraBalls.splice(i,1);continue}
    for(let b of bricks){
      if(!b.alive)continue;
      if(eb.x+ballR>b.x&&eb.x-ballR<b.x+b.w&&eb.y+ballR>b.y&&eb.y-ballR<b.y+b.h){
        b.hp--;if(b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,10);maybeDropPowerup(b.x+b.w/2,b.y+b.h/2);checkUpgradeThreshold()}
        eb.dy=-eb.dy;break;
      }
    }
    if(bossActive&&eb.x+ballR>bossX&&eb.x-ballR<bossX+bossW&&eb.y+ballR>bossY&&eb.y-ballR<bossY+bossH){damageBoss(1);eb.dy=-eb.dy}
  }
  // Lasers
  for(let i=lasers.length-1;i>=0;i--){
    let l=lasers[i];l.y-=8;
    if(l.y<0){lasers.splice(i,1);continue}
    for(let b of bricks){
      if(!b.alive)continue;
      if(l.x>b.x&&l.x<b.x+b.w&&l.y>b.y&&l.y<b.y+b.h){
        b.hp--;if(b.hp<=0){b.alive=false;combo++;score+=50*combo*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,8);maybeDropPowerup(b.x+b.w/2,b.y+b.h/2);checkUpgradeThreshold()}
        lasers.splice(i,1);break;
      }
    }
    if(i<lasers.length&&lasers[i]&&bossActive&&lasers[i].x>bossX&&lasers[i].x<bossX+bossW&&lasers[i].y>bossY&&lasers[i].y<bossY+bossH){damageBoss(1);lasers.splice(i,1)}
  }
  // Powerups
  for(let i=powerups.length-1;i>=0;i--){
    let p=powerups[i];p.y+=p.dy;
    if(p.y>H+20){powerups.splice(i,1);continue}
    if(p.y+10>=py&&p.y<=py+paddleH&&p.x>=px&&p.x<=px+paddleW){
      p.type.apply();sfxPowerup();addFloatText(p.x,p.y,p.type.name,p.type.color,18);
      powerups.splice(i,1);
    }
  }
  // Particles
  for(let i=particles.length-1;i>=0;i--){
    let p=particles[i];p.x+=p.vx;p.y+=p.vy;p.life-=0.025;p.vy+=0.05;
    if(p.life<=0)particles.splice(i,1);
  }
  // Floating texts
  for(let i=floatingTexts.length-1;i>=0;i--){
    let t=floatingTexts[i];t.y+=t.vy;t.life-=0.018;
    if(t.life<=0)floatingTexts.splice(i,1);
  }
  // Stars
  for(let s of stars){s.a+=s.s;if(s.a>1)s.a=0}
  updateShake();
  document.getElementById('scoreVal').textContent=score;
  document.getElementById('comboVal').textContent=combo;
}

function endGame(){
  gameOver=true;running=false;sfxGameOver();
  if(score>hiScore){hiScore=score;localStorage.setItem('neonBreakoutHi',hiScore);document.getElementById('hiVal').textContent=hiScore}
  let o=document.getElementById('overlay');o.style.display='flex';
  let runInfo=buffs.length>0?`<p style="color:#f0f">Upgrades: ${buffs.map(b=>b.name).join(', ')}</p>`:'';
  o.innerHTML=`<h1>GAME OVER</h1><p>Score: ${score}</p><p>Waves Survived: ${wave}</p><p>Max Combo: ${maxCombo}</p><p>Max Difficulty: ${difficultyLevel}</p><p>Upgrades: ${upgradeCount}</p>${runInfo}<p style="color:#ff0;font-size:14px">High Score: ${hiScore}</p><button onclick="startGame()">PLAY AGAIN</button>`;
}
